package com.marketintel.service;
import com.marketintel.model.*; import org.springframework.stereotype.Service; import java.time.*; import java.util.*;
@Service public class BacktestService {
 private final FeatureStoreService store; private final PatternEngineService patterns;
 public BacktestService(FeatureStoreService store,PatternEngineService patterns){this.store=store;this.patterns=patterns;}
 public BacktestResult run(BacktestRequest r){var f=store.load(r.symbol(),r.from(),r.to());if(f.size()<3)throw new IllegalArgumentException("Not enough feature history; build the feature store first.");double cash=r.initialCapital(),peak=cash,maxDd=0;List<BacktestTrade> trades=new ArrayList<>();for(int i=1;i<f.size();i++){var prev=f.get(i-1);var cur=f.get(i);boolean longSignal=switch(r.strategy().toUpperCase()){case "SMA20"->prev.close()<=prev.sma20()&&cur.close()>cur.sma20();case "RSI"->prev.rsi14()<30&&cur.rsi14()>=30;case "PATTERN"->patterns.detect(f.subList(Math.max(0,i-5),i+1)).stream().anyMatch(x->x.timestamp().equals(cur.timestamp())&&x.direction().equals("BULLISH"));default->cur.close()>cur.sma20()&&cur.rsi14()>=50;};if(longSignal){double entry=cur.close();double next=i+1<f.size()?f.get(i+1).close():entry;double capital=cash*r.positionFraction();double qty=capital/entry;double gross=(next-entry)*qty;double cost=(entry+next)*qty*r.transactionCostBps()/10000;double pnl=gross-cost;cash+=pnl;trades.add(new BacktestTrade(cur.timestamp(),i+1<f.size()?f.get(i+1).timestamp():cur.timestamp(),entry,next,qty,pnl,pnl/capital*100,"LONG_SIGNAL"));peak=Math.max(peak,cash);maxDd=Math.max(maxDd,(peak-cash)/peak*100);}}double ret=(cash/r.initialCapital()-1)*100;double wins=trades.stream().filter(t->t.profitLoss()>0).count();return new BacktestResult(r.symbol(),r.strategy(),r.initialCapital(),cash,ret,maxDd,trades.isEmpty()?0:wins/trades.size()*100,trades.size(),trades);}
}